-- Glasshouse POS: run this ONCE in Supabase -> SQL Editor -> New query -> paste -> Run.

-- 1. One table holds everything the app saves (menu, settings, one document per day of orders).
create table if not exists public.docs (
  path text collate "C" primary key,
  data jsonb not null,
  updated_at timestamptz not null default clock_timestamp()
);
create index if not exists docs_updated_idx on public.docs (updated_at);

create or replace function public.docs_touch() returns trigger language plpgsql as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end $$;
drop trigger if exists docs_touch on public.docs;
create trigger docs_touch before insert or update on public.docs for each row execute function public.docs_touch();

-- 2. Lock the table: nobody on the internet can read it. Only the Vercel server (secret key) can.
alter table public.docs enable row level security;
revoke all on public.docs from anon, authenticated;
grant all on public.docs to service_role;

-- 3. Adds orders to a day's document without overwriting orders made on other phones.
create or replace function public.merge_day(p_path text, p_date text, p_orders jsonb) returns void
language plpgsql as $$
begin
  insert into public.docs(path, data) values (p_path, jsonb_build_object('date', p_date, 'orders', p_orders))
  on conflict (path) do update
    set data = jsonb_set(public.docs.data, '{orders}', coalesce(public.docs.data->'orders', '{}'::jsonb) || p_orders);
end $$;
revoke execute on function public.merge_day(text, text, jsonb) from public, anon, authenticated;
grant execute on function public.merge_day(text, text, jsonb) to service_role;

